func constrainedWidth(path string) int {
	for i := len(path) - 1; i >= 0; i-- {
		if path[i] == '/' {
			path = path[i+1:]
			break
		}
	}
	switch path {
	case "EGPRSLevelIEEGPRSLevel":
		return 2
	case "EGPRSModulationAndCodingIEEGPRSModulationAndCodingScheme":
		return 4
	case "EGPRSWindowSizeIEEGPRSWindowSize":
		return 5
	case "ExtensionInformationEGPRSPACKETCHANNELREQUESTGroupEGPRSPACKETCHANNELREQUESTGroupBEPPERIOD":
		return 4
	case "GPRSCellOptionsIENMO":
		return 2
	case "MBMSSessionParametersListIELengthOfMBMSBearerIdentityGroupListEntryLengthOfMBMSBearerIdentity":
		return 3
	case "MBMSSessionParametersListIELengthOfMBMSBearerIdentityGroupListEntryNPMTransferTimeValue":
		return 5
	case "MPRACHControlParametersIES":
		return 4
	}
	return 0
}
